def fibonacci(n):.text:

    if n <= 0: 
        return [] 
    elif n == 1: 
        return [0] 
    elif n == 2: 
        return [0, 1] 
    else: 
        fib = [0, 1] 
        for i in range(2, n): 
            fib.append(fib[i-1] + fib[i-2]) 
        return fib 

# Test the function 
print(fibonacci(10))
